<?php require APP_ROOT.'/services/appointments.php';if($customerPage&&!current_user())$_SESSION['appointment_after_login']='khach_hang/lich_hen.php?'.(preg_match('/^[A-Za-z0-9]{17}$/D',get('vin'))?'vin='.get('vin'):'dat_lich=1');$u=require_role($customerPage?['KHACH_HANG']:['NHAN_VIEN','ADMIN']);$back=($customerPage?'khach_hang':'nhan_vien').'/lich_hen.php';handle_form(fn()=>appointment_action($u,$_POST),$back);page_start('Lịch hẹn xem xe','Yêu cầu đổi giờ chỉ có hiệu lực sau khi phía còn lại đồng ý.');
if($customerPage){echo '<details '.((get('vin')||get('dat_lich')==='1')?'open':'').'><summary>Đặt lịch xem xe</summary>';token_form();field('action','','create','hidden');select_field('vin','Chọn VIN',choices("SELECT x.so_khung_vin,CONCAT(d.ten_dong_xe,' · ',x.mau_sac,' · ',x.so_khung_vin) ten FROM xe x JOIN dong_xe d ON d.ma_dong_xe=x.ma_dong_xe WHERE x.trang_thai<>'DA_BAN_GIAO' AND d.hien_thi=1",'so_khung_vin','ten'),get('vin'),true);field('bat_dau','Bắt đầu','','datetime-local','required');field('ket_thuc','Kết thúc','','datetime-local','required');textarea('ghi_chu','Nhu cầu / ghi chú');echo '<button>Gửi lịch hẹn</button></form></details>';}
$where=$customerPage?'r.khach_hang_id='.(int)$u['id']:($u['quyen']==='ADMIN'?'1=1':'(r.nhan_vien_id='.(int)$u['id'].' OR r.nhan_vien_id IS NULL) AND r.ma_showroom IN(SELECT ma_showroom FROM pham_vi_showroom WHERE tai_khoan_id='.(int)$u['id'].')');
foreach(db_all("SELECT r.*,t.ho_ten FROM lich_hen r JOIN tai_khoan t ON t.id=r.khach_hang_id WHERE $where ORDER BY r.bat_dau DESC LIMIT 150")as$r){echo '<section class="panel"><h2>#'.(int)$r['id'].' · '.e($r['so_khung_vin']).'</h2><p>'.e($r['ho_ten'].' · '.$r['ma_showroom']).' '.badge($r['trang_thai']).'</p><p>'.e($r['bat_dau'].' → '.$r['ket_thuc']).'</p>';if($r['yeu_cau_loai'])notice($r['yeu_cau_loai']==='DOI_GIO'?'Đề xuất: '.$r['de_xuat_bat_dau'].' → '.$r['de_xuat_ket_thuc']:'Đang yêu cầu hủy: '.$r['yeu_cau']);
if(!in_array($r['trang_thai'],['DA_HUY','DA_DEN','KHONG_DEN'],true)){token_form();field('id','',$r['id'],'hidden');if(!$customerPage&&$u['quyen']==='ADMIN')select_field('nhan_vien_id','Nhân viên xác nhận',choices("SELECT id,ho_ten FROM tai_khoan WHERE quyen='NHAN_VIEN' AND trang_thai='HOAT_DONG'",'id','ho_ten'),$r['nhan_vien_id']);echo '<div class="row">';field('bat_dau','Giờ mới đề xuất','','datetime-local');field('ket_thuc','Kết thúc mới','','datetime-local');echo '</div>';textarea('ghi_chu','Lý do / kết quả');echo '<div class="actions"><button name="action" value="propose" class="ghost">Đề xuất đổi giờ</button>';if($r['yeu_cau_loai']==='DOI_GIO'&&(int)$r['nguoi_de_xuat_id']!==(int)$u['id'])echo '<button name="action" value="accept">Đồng ý giờ đề xuất</button>';if($customerPage)echo '<button name="action" value="request_cancel" class="danger">Yêu cầu hủy</button>';else {if($r['trang_thai']==='CHO_XAC_NHAN')echo '<button name="action" value="confirm">Xác nhận lịch</button>';echo '<button name="action" value="cancel" class="danger">Xác nhận hủy</button>';if($r['trang_thai']==='DA_XAC_NHAN'&&strtotime($r['ket_thuc'])<=time()){select_field('ket_qua_loai','Kết quả',['DA_DEN'=>'Khách đã đến','KHONG_DEN'=>'Khách không đến']);echo '<button name="action" value="result" class="ghost">Lưu kết quả</button>';}}echo '</div></form>';}
echo '<details><summary>Lịch sử xử lý</summary>';foreach(db_all('SELECT h.*,t.ho_ten FROM lich_hen_lich_su h JOIN tai_khoan t ON t.id=h.nguoi_thao_tac_id WHERE lich_hen_id=? ORDER BY h.id DESC',[$r['id']])as$l)echo '<p>'.e($l['thoi_gian'].' · '.$l['ho_ten'].' · '.$l['hanh_dong']).'</p>';echo '</details></section>';}
page_end();
